head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#tabControll1_contents_content1_body_grid1_column2', 'drag-n-drop', {
        dx: 0,
        dy: -50
    });
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById('tabControll1_contents_content1_body_grid1_body_tbody').children[6].innerText.indexOf('가1') == 0;
}
scwin.unitTest = function() {
    //Init test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControll1_contents_content1_body_grid1_cell_0_1').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_tabControll1_contents_content1_body_grid1___selectbox_col2_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControll1_contents_content1_body_grid1_column2').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop unit Test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
